import React, { useState } from "react";
import NavbarPlayer from "./components/NavbarPlayer";
import "./components/navbar.css";

const fetchDesignersByName = async (name) => {
  try {
    const response = await fetch(`http://localhost:8080/user-profile?username?=${name}`);
    if (response.ok) {
      const result = await response.json();
      if (result.responseHeader === "OK" && result.designers.length > 0) {
        return result.designers; // فرض کنید داده‌ها در فیلد `designers` قرار دارند
      } else if (result.responseHeader === "OK" && result.designers.length === 0) {
        throw new Error("طراحی با این نام پیدا نشد.");
      } else {
        throw new Error("خطایی در دریافت اطلاعات رخ داده است.");
      }
    } else {
      throw new Error("خطا در برقراری ارتباط با سرور.");
    }
  } catch (error) {
    console.error("Error fetching designers:", error.message);
    return { error: error.message };
  }
};

const DesignerSearch = () => {
  const [searchTerm, setSearchTerm] = useState("");
  const [searchResults, setSearchResults] = useState([]);
  const [errorMessage, setErrorMessage] = useState("");

  const handleSearchClick = async () => {
    if (searchTerm.trim()) {
      const result = await fetchDesignersByName(searchTerm);
      if (result.error) {
        setSearchResults([]);
        setErrorMessage(result.error);
      } else {
        setSearchResults(result);
        setErrorMessage("");
      }
    } else {
      setSearchResults([]);
      setErrorMessage("لطفاً یک نام وارد کنید.");
    }
  };

  const handleFollow = (designerId) => {
    fetch(`http://localhost:8080/follow/${designerId}`, { method: "POST" })
      .then((response) => {
        if (response.ok) {
          alert("طراح با موفقیت دنبال شد.");
        } else {
          alert("خطا در دنبال کردن طراح.");
        }
      })
      .catch((error) => {
        console.error("Error following designer:", error);
      });
  };

  return (
    <div>
      <NavbarPlayer />
      <div className="main-container">
        <h1>جستجوی طراحان</h1>
        <input
          type="text"
          placeholder="نام طراح را وارد کنید..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="search-input"
        />
        <button onClick={handleSearchClick} className="search-button">
          جستجو
        </button>
        {errorMessage && <p className="error-message">{errorMessage}</p>}
        <div className="results-container">
          {searchResults.map((designer) => (
            <div key={designer.id} className="designer-card">
              <p>{designer.name}</p>
              <button onClick={() => handleFollow(designer.id)}>دنبال کردن</button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default DesignerSearch;
